        "تحميل العينات بداخل الكاسيت المخصص وإدخال بيانات المريض وهرمونات الفحص المطلوبة بالبرنامج.",
        "التأكد من وجود الكواشف (Reagents)، محاليل الركيزة الضوئية (Substrates)، أكواب التفاعل (Cuvettes)، ومحلول الغسيل بالحجم الكافي.",
