    "principle": "CK-MB هو شكل من أشكال CK أكثر ارتباطاً بالقلب ويمكن قياسه كنشاط إنزيمي أو كنسبة مقارنةً بالـ CK الكلي.",
    "clinicalSignificance": "ارتفاع CK-MB قد يدل على إصابة قلبية لكنه أقل خصوصية من التروبونين وقد يرتفع أيضاً نتيجة إصابة عضلية غير قلبية، لذا يجب التقييم السريري المشترك.",
