    "clinicalSignificance": "زمن نزف مطوّل قد يدل على نقص عدد الصفائح أو اضطراب وظيفتها أو مرض Von Willebrand أو تأثير الأسبرين، لكن نتيجة واحدة محدودة الدلالة وتخضع لتباين منهجي عالٍ. القيم الأقصر أو داخل النطاق قد لا تستبعد اضطرابات وظيفية أخرى.",
