    "clinicalSignificance": "ارتفاع ACT يدل عادة على تأثير هيبارين عالي الجرعة أو نقص عوامل التجلط أو تأثيرات فسيولوجية مثل Hypothermia، بينما الانخفاض قد يعكس ضعف تثبيط التجلط خلال المراقبة العلاجية. تفسير القيم يجب أن يكون ضمن بروتوكولات الإجراء السريرية والمعايير المستهدفة ولا يُعتمد عليها وحدها.",
