    "principle": "يُكشف D‑Dimer بواسطة اختبارات مناعية أو طرق قياسية لاكتشاف نواتج تحلل الفايبرين المترابط في البلازما، وتُعطي قيماً كمية أو نصف كمية حسب الطريقة.",
