    "simpleExplanation": "قيمة D‑Dimer تعكس وجود تجلط متحلل في الجسم؛ نتيجة مرتفعة تعني وجود تحلل خثرة محتمل، ونتيجة منخفضة قد تساعد في الاستبعاد عندما يكون الاحتمال السريري منخفضاً.",
    "rangeCaveat": "تُعتمد الحدود المرجعية والوحدات على منهجية وتحليل المختبر وعوامل المريض مثل العمر والحمل، لذا تختلف القيم بين المختبرات ويجب الرجوع إلى مرجع المختبر."
