    "clinicalSignificance": "العيار المرتفع إلى أو فوق العيار الحرج قد يدل على زيادة خطر HDFN ويستلزم متابعة متخصصة، والانخفاض يشير إلى مستوى أجسام مضادة أقل مع ضرورة تقييم سريري مستمر.",
    "preAnalyticalNotes": "يؤخذ المصل أو بلازما الأم ويجب توثيق تاريخ نقل الدم أو إعطاء غلوبيولين مناعي لأنهما قد يؤثران على العيار؛ تجنب عينات مهوَّلة أو غير معروفة المصدر.",
