    "preAnalyticalNotes": "تؤخذ عينة دم كامل معمرة ب‑EDTA مع الحرص على تجنُّب تلوث العينة بدم الأم ووضع تعريف واضح للعينة.",
    "simpleExplanation": "يحدد الاختبار فصيلة وخطورة الرايزيس لخلايا الدم الحمراء عند المولود عبر اختبار المعايرة الأمامية.",
    "rangeCaveat": "قِيَم المرجع والوحدات تعتمد على المختبر والطريقة وعوامل المريض."
