    "clinicalSignificance": "نتيجة تفاعلية تتطلب إجراءات تأكيدية وسياسات بنك الدم المناسبة، بينما تعني نتيجة غير تفاعلية عدم وجود تفاعل قابل للكشف في الفحوصات المطبقة.",
